const wait = (delay) => new Promise((resolve) => setTimeout(resolve, delay));


async function rollToolButton(html, adv, token) {
  let selectedAbility = html.find("[id=ability]")[0].value;
  let expertise = html.find("[name=expertise]")[0].checked;
  let tool = html.find("[id=tools]")[0].value;
  switch(adv) {
    case 'adv':
      diceRoll = "2d20kh1";
      break;
    case 'disadv':
      diceRoll = "2d20kl1";
      break;
    default:
      diceRoll = "1d20";
      break;
  }
  if (tool) {
    rollToolCheck(token.actor, tool.replaceAll('-',' '), diceRoll, selectedAbility, expertise)
  }
}

async function rollToolCheck(actor, tool, diceRoll, ability, expertise) {
  let actorData = actor.system
  let mod = actorData.abilities[ability].mod;

  let abilityNames = {
    'str': 'Strength',
    'dex': 'Dexterity',
    'con': 'Constitution',
    'int': 'Intelligence',
    'wis': 'Wisdom',
    'cha': 'Charisma'
  }

  let proficiency = expertise ? actorData.attributes.prof * 2 : actorData.attributes.prof;

  let roll = await new Roll(`${diceRoll}+${mod}+${proficiency}`).roll({async: true});

  ChatMessage.create({
    type: CONST.CHAT_MESSAGE_TYPES.ROLL,
    rolls: [roll],
    rollMode: game.settings.get("core", "rollMode"),
    user: game.user._id,
    speaker: ChatMessage.getSpeaker({token: actor}),
    flavor: `${tool} - Tool Check (${abilityNames[ability]})`
  })
}

let selectedToolProfs = token.actor.system.traits.toolProf.selected;
let tools = Object.values(selectedToolProfs)

let abilityScoreSelector = `
<div>
  <label>Select ability score:</label>
  <select id="ability" name="ability">
    <option value="str">Strength</option>
    <option value="dex">Dexterity</option>
    <option value="con">Constitution</option>
    <option value="int" selected>Intelligence</option>
    <option value="wis">Wisdom</option>
    <option value="cha">Charisma</option>
  </select>
</div>
`

let toolOptions = tools.map(tool => 
  `<option value=${tool.replaceAll(' ','-')}>${tool}</option>`
).reduce((r,opt) => r.concat(opt), '<option disabled value selected />')

let toolSelector = `
<div>
<label>Select tool:</label>
<select id="tools" name="tools">${toolOptions}</select>
</div>`

let expertiseSelector = `
<div><label>Expertise?</label><input name="expertise" type="checkbox"/></div>
`

let dialogHtml = '<div>' + abilityScoreSelector.concat(toolSelector) + '</div>'.concat(expertiseSelector);


let d = new Dialog({
  title: "Tool Check",
  content: dialogHtml,
  buttons: {
    advantage: {
      label: "Advantage",
      callback: (html) => rollToolButton(html, "adv", token)
    },
    normal: {
      label: "Normal",
      callback: (html) => rollToolButton(html, "norm", token)
    },
    disadvantage: {
      label: "Disadvantage",
      callback: (html) => rollToolButton(html, "disadv", token)
    },
  }
})
d.render(true)
